candidate.formal_statement_latex:
Fix a family of groups $\mathbb{G}=\mathbb{G}(\lambda)$ of prime order $p=p(\lambda)$ and a random oracle $\mathcal{H}$ for groups as in Definition~\ref{def:ggmrom}. Then there does not exist a round-optimal blind signature scheme $\mathsf{BS}=(\mathsf{KeyGen},\mathsf{User}_1,\mathsf{Sign},\mathsf{User}_2,\mathsf{Verify})$ in the ROM with message space $\mathcal{M}=\mathcal{M}(\lambda)$ (Definition~\ref{def:bs}) for which all of the following hold simultaneously:
\begin{enumerate}
  \item $\mathsf{BS}$ is correct (Definition~\ref{def:bs});
  \item the algorithms $\mathsf{User}_1$, $\mathsf{User}_2$ and $\mathsf{Verify}$ are transformations of GGM algorithms $\overline{\mathsf{User}_1}$, $\overline{\mathsf{User}_2}$ and $\overline{\mathsf{Verify}}$ in the sense of Definition~\ref{def:ggmrom};
  \item $|\mathcal{M}(\lambda)|$ is superpolynomial in $\lambda$, i.e.\ $|\mathcal{M}(\lambda)|=\lambda^{\omega(1)}$;
  \item for every ppt GGM blindness adversary $\overline{\mathcal{S}}$, the advantage $\mathrm{adv}^{\mathbf{blind}}_{\mathsf{BS},\mathcal{S}}(\lambda)$ (Definition~\ref{def:blind}) is negligible in $\lambda$;
  \item for every computationally unbounded GGM one-more-unforgeability adversary $\overline{\mathcal{U}}$ that makes at most a polynomial number of calls to its oracles $\mathcal{O}_{\mathsf{grp}}$, $\overline{\mathcal{H}}$ and $\overline{\mathcal{O}_{\mathsf{Sign}}}$, the advantage $\mathrm{adv}^{\mathbf{omuf}}_{\mathsf{BS},\mathcal{U}}(\lambda)$ (Definition~\ref{def:omuf}) is negligible in $\lambda$.
\end{enumerate}
Equivalently, writing $q:=q_{\mathsf{User}_2}+q_{\mathsf{Verify}}$ for the total number of $\mathcal{H}$-queries made by $\mathsf{User}_2$ and $\mathsf{Verify}$: for every polynomial $Q$ there is no scheme as above with $q(\lambda)\le Q(\lambda)$. The case $q(\lambda)\le O(\log\lambda)$ is a theorem \cite{DKT26}; the conjecture is that the restriction $q \le O(\log \lambda)$ may be dropped, no other hypothesis being changed. Note that no bound on $q_{\mathsf{KeyGen}}$, $q_{\mathsf{User}_1}$ or $q_{\mathsf{Sign}}$ is imposed beyond the polynomial bound implied by these algorithms being ppt.

candidate.definitions_latex:
\begin{definition}[GGM+ROM]\label{def:ggmrom}
Let $\mathbb{G}=\mathbb{G}(\lambda)$ be a family of groups of prime order $p=p(\lambda)$, written additively, with neutral element $\mathfrak{o}$ and a fixed generator $\mathfrak{1}$. In Maurer's generic group model \cite{Mau05} a \emph{GGM algorithm} $\overline{A}$ never sees elements of $\mathbb{G}$: it manipulates indices (labels) into a table $\mathtt{T}$ of group elements which is initialized with $\mathfrak{1}$ followed by $\overline{A}$'s group-element inputs. It has access to two group oracles: $\mathcal{O}_{\mathsf{eq}}(i,j)$ returns $1$ if $\mathtt{T}[i]=\mathtt{T}[j]$ and $0$ otherwise, and $\mathcal{O}_{\mathsf{grp}}(i,j)$ appends $\mathtt{T}[i]+\mathtt{T}[j]$ to $\mathtt{T}$ and returns its index. The output of $\overline{A}$ consists of a list of indices together with a bitstring. Every GGM algorithm $\overline{A}$ induces an ordinary algorithm $A$, called its \emph{transformation}, which takes and returns actual group elements and maintains the table $\mathtt{T}$ externally.

A \emph{random oracle for groups} with $n^{\mathsf{H}}$ input group elements and output length $r=r(\lambda)$ is a uniformly random function $\mathcal{H}:\mathbb{G}^{n^{\mathsf{H}}}\times\{0,1\}^{*}\to\{0,1\}^{r}$. A GGM algorithm queries it through an oracle $\overline{\mathcal{H}}$ by supplying $n^{\mathsf{H}}$ indices and a bitstring, which are translated into the corresponding group elements before $\mathcal{H}$ is evaluated; the answer is a bitstring. The \emph{GGM+ROM} is the model in which all algorithms and adversaries are GGM algorithms with access to $\mathcal{O}_{\mathsf{eq}}$, $\mathcal{O}_{\mathsf{grp}}$ and $\overline{\mathcal{H}}$.
\end{definition}

\begin{definition}[Round-optimal blind signature and correctness]\label{def:bs}
A \emph{round-optimal blind signature scheme} in the ROM with message space $\mathcal{M}=\mathcal{M}(\lambda)$ is a tuple $\mathsf{BS}=(\mathsf{KeyGen},\mathsf{User}_1,\mathsf{Sign},\mathsf{User}_2,\mathsf{Verify})$ of ppt algorithms with access to $\mathcal{H}$, where for fixed polynomials $n^{\mathsf{vk}},n^{\mathsf{st}},n^{\mathsf{msgU}},n^{\mathsf{msgS}},n^{\mathsf{sig}}$ in $\lambda$:
\begin{itemize}
  \item $\mathsf{KeyGen}^{\mathcal{H}}(1^{\lambda})$ outputs $(\mathsf{sk},\mathsf{vk})$ with $\mathsf{sk}\in\{0,1\}^{*}$ and $\mathsf{vk}\in\mathbb{G}^{n^{\mathsf{vk}}}\times\{0,1\}^{*}$;
  \item $\mathsf{User}_1^{\mathcal{H}}(\mathsf{vk},m)$, for $m\in\mathcal{M}$, outputs a user message $\mathsf{msgU}\in\mathbb{G}^{n^{\mathsf{msgU}}}\times\{0,1\}^{*}$ and a state $\mathsf{stU}\in\mathbb{G}^{n^{\mathsf{st}}}\times\{0,1\}^{*}$;
  \item $\mathsf{Sign}^{\mathcal{H}}(\mathsf{sk},\mathsf{msgU})$ outputs a signer message $\mathsf{msgS}\in\mathbb{G}^{n^{\mathsf{msgS}}}\times\{0,1\}^{*}$;
  \item $\mathsf{User}_2^{\mathcal{H}}(\mathsf{stU},\mathsf{msgS})$ outputs a signature $\sigma\in\mathbb{G}^{n^{\mathsf{sig}}}\times\{0,1\}^{*}$;
  \item $\mathsf{Verify}^{\mathcal{H}}(\mathsf{vk},m,\sigma)$ deterministically outputs a bit.
\end{itemize}
We write $\langle\mathsf{User}^{\mathcal{H}}(\mathsf{vk},m),\mathsf{Sign}^{\mathcal{H}}(\mathsf{sk})\rangle$ for the sequential execution $(\mathsf{msgU},\mathsf{stU})\leftarrow\mathsf{User}_1^{\mathcal{H}}(\mathsf{vk},m)$, $\mathsf{msgS}\leftarrow\mathsf{Sign}^{\mathcal{H}}(\mathsf{sk},\mathsf{msgU})$, $\sigma\leftarrow\mathsf{User}_2^{\mathcal{H}}(\mathsf{stU},\mathsf{msgS})$, whose output is $\sigma$. For an algorithm $A$ we write $q_{A}=q_{A}(\lambda)$ for an upper bound on the number of calls to $\mathcal{H}$ made by $A$.

$\mathsf{BS}$ is \emph{correct} if for every $m\in\mathcal{M}(\lambda)$,
\[
\Pr\bigl[(\mathsf{sk},\mathsf{vk})\leftarrow\mathsf{KeyGen}^{\mathcal{H}}(1^{\lambda}),\ \sigma\leftarrow\langle\mathsf{User}^{\mathcal{H}}(\mathsf{vk},m),\mathsf{Sign}^{\mathcal{H}}(\mathsf{sk})\rangle:\mathsf{Verify}^{\mathcal{H}}(\mathsf{vk},m,\sigma)=1\bigr]\ \ge\ 1-\mathrm{negl}(\lambda),
\]
the probability being over $\mathcal{H}$ and the coins of the algorithms.
\end{definition}

\begin{definition}[Blindness]\label{def:blind}
For a scheme $\mathsf{BS}$ and an adversary $\mathcal{S}$, the game $\mathbf{blind}_{\mathsf{BS},\mathcal{S}}$ samples $b\leftarrow_{\$}\{0,1\}$ and a random oracle $\mathcal{H}$ and runs $b'\leftarrow\mathcal{S}^{\mathcal{H},\mathcal{O}_{\mathsf{init}},\mathcal{O}_{\mathsf{User}_1,0},\mathcal{O}_{\mathsf{User}_1,1},\mathcal{O}_{\mathsf{User}_2,0},\mathcal{O}_{\mathsf{User}_2,1}}(1^{\lambda})$, where
\begin{itemize}
  \item $\mathcal{O}_{\mathsf{init}}(\mathsf{vk},m_{0},m_{1})$ may be called at most once and stores $\mathsf{vk},m_{0},m_{1}$;
  \item $\mathcal{O}_{\mathsf{User}_1,c}()$, for $c\in\{0,1\}$, may be called at most once each and only after $\mathcal{O}_{\mathsf{init}}$, runs $(\mathsf{stU}_{c},\mathsf{msgU}_{c})\leftarrow\mathsf{User}_1^{\mathcal{H}}(\mathsf{vk},m_{b\oplus c})$ and returns $\mathsf{msgU}_{c}$;
  \item $\mathcal{O}_{\mathsf{User}_2,c}(\mathsf{msgS}_{c})$, for $c\in\{0,1\}$, may be called at most once each and only after $\mathcal{O}_{\mathsf{User}_1,c}$, computes and stores $\sigma_{b\oplus c}\leftarrow\mathsf{User}_2^{\mathcal{H}}(\mathsf{stU}_{c},\mathsf{msgS}_{c})$; if $\mathcal{O}_{\mathsf{User}_2,1\oplus c}$ was already called and $\mathsf{Verify}^{\mathcal{H}}(\mathsf{vk},m_{c},\sigma_{c})=1$ for both $c=0,1$, it returns $(m_{0},\sigma_{0})$ and $(m_{1},\sigma_{1})$, and otherwise $\bot$.
\end{itemize}
The advantage is $\mathrm{adv}^{\mathbf{blind}}_{\mathsf{BS},\mathcal{S}}:=2\cdot\bigl|\Pr[b=b']-\tfrac{1}{2}\bigr|$.
\end{definition}

\begin{definition}[One-more unforgeability]\label{def:omuf}
For a scheme $\mathsf{BS}$ and an adversary $\mathcal{U}$, the game $\mathbf{omuf}_{\mathsf{BS},\mathcal{U}}$ samples a random oracle $\mathcal{H}$ and $(\mathsf{sk},\mathsf{vk})\leftarrow\mathsf{KeyGen}^{\mathcal{H}}(1^{\lambda})$, runs $(m_{i},\sigma_{i})_{i\in[\ell+1]}\leftarrow\mathcal{U}^{\mathcal{H},\mathcal{O}_{\mathsf{Sign}}}(1^{\lambda},\mathsf{vk})$ where $\mathcal{O}_{\mathsf{Sign}}(\cdot):=\mathsf{Sign}^{\mathcal{H}}(\mathsf{sk},\cdot)$ and $\ell$ is the number of calls $\mathcal{U}$ made to $\mathcal{O}_{\mathsf{Sign}}$, and outputs $1$ if $m_{i}\ne m_{j}$ for all $i\ne j$ and $\mathsf{Verify}^{\mathcal{H}}(\mathsf{vk},m_{i},\sigma_{i})=1$ for all $i\in[\ell+1]$. The advantage is $\mathrm{adv}^{\mathbf{omuf}}_{\mathsf{BS},\mathcal{U}}:=\Pr[\mathbf{omuf}_{\mathsf{BS},\mathcal{U}}=1]$.
\end{definition}
